refentry.refsect1:
&reftitle.description;
arrayarray_diff arrayarray arrayarrays
array लाई एक वा सोभन्दा बढी अन्य arrays सँग तुलना गर्दछ र अन्य कुनै पनि arrays मा नभएका array का values return गर्दछ।

  &reftitle.examples;



    array_diff को उदाहरण


<?php
$array1 = array("a" => "green", "red", "blue", "red");
$array2 = array("b" => "green", "yellow", "red");
$result = array_diff($array1, $array2);

print_r($result);
?>



$array1 मा दोहोरिएका सबै प्रविष्टिहरूलाई एकै तरिकाले व्यवहार गरिन्छ। यसले निम्न output दिनेछ:


Array
(
    [1] => blue
)






दुईवटा elements तब र केवल तब मात्र बराबर मानिन्छन् जब (string) $elem1 === (string) $elem2 हुन्छ। अर्थात्, जब string representation एउटै हुन्छ।




    नमिल्ने types सहितको array_diff उदाहरण


<?php
// This will generate a Notice that an array cannot be cast to a string.
$source = [1, 2, 3, 4];
$filter = [3, 4, [5], 6];
$result = array_diff($source, $filter);

// Whereas this is fine, since the objects can cast to a string.
class S {
  private $v;

  public function __construct(string $v) {
    $this->v = $v;
  }

  public function __toString() {
    return $this->v;
  }
}

$source = [new S('a'), new S('b'), new S('c')];
$filter = [new S('b'), new S('c'), new S('d')];

$result = array_diff($source, $filter);

// $result now contains one instance of S('a');
var_dump($result);
?>





वैकल्पिक comparison function प्रयोग गर्न, array_udiff हेर्नुहोस्।
